// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.initialize();
        address ownerAfterInit = c.owner();
        // The general rule: after initialization, owner() must be the caller (msg.sender)
        // because __Ownable_init_unchained transfers ownership to _msgSender().
        assertTrue(ownerAfterInit == caller);
    }
}

